python -c "
import semver

v = semver.VersionInfo(1, 2, 3)

# Test all comparisons with strings
ops = ['==', '!=', '<', '<=', '>', '>=']
for op in ops:
    try:
        result = eval(f'v {op} \"1.2.3\"')
        print(f'{op} \"1.2.3\": {result}')
    except TypeError as e:
        print(f'{op} \"1.2.3\": TypeError - {e}')

print()

# Test with integers
for op in ops:
    try:
        result = eval(f'v {op} 123')
        print(f'{op} 123: {result}')
    except TypeError as e:
        print(f'{op} 123: TypeError - {e}')
"
